//! Helpers shared by the integration tests.
#![allow(dead_code)]

use serde_json::Value;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};

/// The text of a fixture in `tests/fixtures` (generated by `generate.js` from the web model).
pub fn fixture(name: &str) -> String {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures").join(name);
    std::fs::read_to_string(&path).unwrap_or_else(|error| panic!("{}: {error}", path.display()))
}

/// The first difference between two JSON values, or `None` when they are semantically identical:
/// same structure, same strings and booleans, numbers equal by value (`1` and `1.0` are the same
/// JSON number), object key order ignored.
pub fn difference(left: &Value, right: &Value, path: &str) -> Option<String> {
    match (left, right) {
        (Value::Number(a), Value::Number(b)) => {
            let same = match (a.as_i64(), b.as_i64(), a.as_u64(), b.as_u64()) {
                (Some(x), Some(y), _, _) => x == y,
                (_, _, Some(x), Some(y)) => x == y,
                _ => a.as_f64() == b.as_f64(),
            };
            (!same).then(|| format!("{path}: {a} != {b}"))
        }
        (Value::Array(a), Value::Array(b)) => {
            if a.len() != b.len() {
                return Some(format!("{path}: array length {} != {}", a.len(), b.len()));
            }
            a.iter().zip(b).enumerate().find_map(|(index, (x, y))| difference(x, y, &format!("{path}/{index}")))
        }
        (Value::Object(a), Value::Object(b)) => {
            for key in a.keys() {
                if !b.contains_key(key) {
                    return Some(format!("{path}/{key}: missing on the right"));
                }
            }
            for key in b.keys() {
                if !a.contains_key(key) {
                    return Some(format!("{path}/{key}: missing on the left"));
                }
            }
            a.iter().find_map(|(key, x)| difference(x, &b[key], &format!("{path}/{key}")))
        }
        (a, b) => (a != b).then(|| format!("{path}: {a} != {b}")),
    }
}

/// A fresh, empty folder under the system's temporary directory, removed when dropped.
pub struct TempDir(pub PathBuf);

impl TempDir {
    pub fn new(label: &str) -> TempDir {
        static COUNTER: AtomicUsize = AtomicUsize::new(0);
        let name = format!("st-project-{label}-{}-{}", std::process::id(), COUNTER.fetch_add(1, Ordering::Relaxed));
        let path = std::env::temp_dir().join(name);
        let _ = std::fs::remove_dir_all(&path);
        std::fs::create_dir_all(&path).expect("temporary folder");
        // Tests compare against canonical paths (macOS's /var is a link to /private/var).
        TempDir(std::fs::canonicalize(&path).expect("canonical temporary folder"))
    }
    pub fn path(&self) -> &Path {
        &self.0
    }
    pub fn join(&self, name: &str) -> PathBuf {
        self.0.join(name)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// The smallest project the host accepts, as the Swift store tests used: one track, one
/// instrument with `sample`, one empty pattern.
pub fn minimal(sample: Option<&Path>) -> st_project::Project {
    let sample = sample.map(|path| path.to_string_lossy().into_owned()).unwrap_or_default();
    st_project::Project::from_value(serde_json::json!({
        "version": 1, "name": "Test", "bpm": 120.0, "tracks": [{ "id": 0 }],
        "instruments": [{ "id": 0, "samplePath": sample }],
        "patterns": [{ "id": 0, "length": 64, "steps": [[]] }], "sequence": [0]
    }))
    .expect("minimal project")
}
